   x0=(i%6)*160;y0=(i//6)*240;room=Image.open(O/c['room']).convert('RGB');x=255+(c['foot'][0]-7680)*398/384;y=287+(c['foot'][1]-8064)*398/384;b.paste(room.crop((round(x)-75,round(y)-130,round(x)+75,round(y)+35)),(x0+5,y0));src=Image.open(O/c['source']).convert('RGBA');px,py=(128,224) if src.width==256 else (92,172);scale=82/148;src=src.resize((round(src.width*scale),round(src.height*scale)),Image.Resampling.LANCZOS);b.paste(src,(round(x0+80-px*scale),round(y0+225-py*scale)),src);dr.text((x0+3,y0+227),f"{c['index']} / {c['time']-j['plan']['started']:.2f}s",fill='white')
